SELECT p.*, c.name AS category_name, u.nickname AS seller_nickname, u.phone AS seller_phone, u.avatar AS seller_avatar
FROM product p
LEFT JOIN category c ON p.category_id = c.id
LEFT JOIN user u ON p.user_id = u.id


